// Meta's webhook → which WhatsApp number it came to, plus the exact raw body for the
// X-Hub-Signature-256 check (Webhook node: Options → Raw Body ON). Meta already got its 200.
const item = $input.first();
const headers = item.json.headers || {};
let raw = '';
try { raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'); } catch (e) { raw = ''; }
let body = item.json.body;
if (!body || typeof body !== 'object' || !Object.keys(body).length) {
  try { body = JSON.parse(raw); } catch (e) { body = {}; }
}
if (!raw) raw = JSON.stringify(body);

let pnid = '';
for (const e of body.entry || []) for (const ch of e.changes || []) {
  const id = ((ch.value || {}).metadata || {}).phone_number_id;
  if (id) { pnid = String(id); break; }
}
if (!pnid) return [];                                  // not a WhatsApp event we handle
return [{ json: { phone_number_id: pnid, signature: String(headers['x-hub-signature-256'] || ''), raw, body } }];

// feeder.retexia.com → n8n (X-Retexia-Key checked by the webhook's Header Auth credential).
//   test_bot: one message through the real pipeline in test mode (nothing sent to WhatsApp)
//   check:    is this seller's number + token working? (Test connection)
//   send:     the seller's reply from the Inbox (free text, inside WhatsApp's 24 h window)
const b = $('Panel: Lingo').first().json.body || {};
const seller = Number(b.lingo_user_id);
if (!Number.isSafeInteger(seller) || seller <= 0) throw new Error('lingo_user_id is required');
const action = String(b.action || '');
const cut = (s, n) => { s = String(s || '').trim(); return s.length > n ? s.slice(0, n) : s; };

if (action === 'test_bot') {
  const session = String(b.session || '').toLowerCase().replace(/[^a-z0-9-]/g, '').slice(0, 40) || 'panel';
  const tap = b.tap && b.tap.id ? { id: cut(b.tap.id, 60), title: cut(b.tap.title, 60) } : null;
  const text = cut(b.text, 1500);
  if (!text && !tap) throw new Error('text or tap is required');
  return [{ json: { action, lingo_user_id: seller, message: {
    phone: 'test-' + session, waId: 'test.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8), name: 'Test customer',
    text: tap ? `[tapped: ${tap.title}]` : text, media: null, tap, quotedId: cut(b.quoted_id, 120), referral: null,
    ts: Math.floor(Date.now() / 1000), start_product: Number(b.start_product) || null,
  } } }];
}
if (action === 'check') return [{ json: { action, lingo_user_id: seller } }];
if (action === 'send') {
  const to = String(b.to || '').replace(/\D/g, '');
  const text = cut(b.text, 4000);
  if (!/^\d{6,20}$/.test(to) || !text) throw new Error('to and text are required');
  return [{ json: { action, lingo_user_id: seller, to, text } }];
}
throw new Error('unknown action');

// The answer to feeder.retexia.com for "check" (Test connection), "send" (Inbox reply) or an unknown seller.
const a = $('Panel Action').first().json;
const s = $('Seller').first().json;
const err = r => {
  const e = (r && (r.error || (r.body && r.body.error))) || null;
  if (!e) return '';
  return typeof e === 'string' ? e : `${e.code ? '(' + e.code + ') ' : ''}${e.error_user_msg || e.message || 'error'}`.slice(0, 300);
};
const body = r => (r && r.body !== undefined ? r.body : r) || {};

if (!s.ok) return [{ json: { reply: { ok: false, error: s.why || 'unknown seller' } } }];
if (!s.token || !s.phone_number_id) return [{ json: { reply: { ok: false, error: 'No WhatsApp number or token saved yet.' } } }];

if (a.action === 'check') {
  const info = $('WA: Number Info').first().json;
  const apps = $('WA: Subscribed Apps').isExecuted ? $('WA: Subscribed Apps').first().json : null;
  const e = err(info);
  const i = body(info);
  const subscribed = apps && !err(apps) ? (body(apps).data || []).length > 0 : null;
  return [{ json: { reply: {
    ok: !e && !!i.id, error: e || (i.id ? null : 'WhatsApp did not answer'),
    info: e ? null : { display_phone_number: i.display_phone_number || '', verified_name: i.verified_name || '', quality_rating: i.quality_rating || '',
                       code_verification_status: i.code_verification_status || '', name_status: i.name_status || '', platform_type: i.platform_type || '' },
    subscribed, subscribe_error: apps ? err(apps) || null : null,
  } } }];
}

// send
const r = $('WA: Send Reply').first().json;
const e = err(r);
const id = ((body(r).messages || [])[0] || {}).id || null;
return [{ json: { reply: { ok: !e && !!id, wa_id: id, error: e || (id ? null : 'WhatsApp did not accept the message') } } }];

// Checks Meta's signature with this number's app secret (Retexia's in embedded mode), then splits
// the webhook: delivery statuses, the seller's own replies from the WhatsApp Business app (echoes)
// and the customer's message(s). Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n server.
const crypto = require('crypto');
const cfg = $('Config').first().json;
const w = $('Read Webhook').first().json;
const num = $('Number').first().json;
const cut = (s, n) => { s = String(s || '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '…' : s; };

const secret = num.connect_mode === 'embedded' ? String(cfg.RETEXIA_APP_SECRET || '') : String(num.app_secret || '');
const expect = 'sha256=' + crypto.createHmac('sha256', secret).update(Buffer.from(w.raw, 'utf8')).digest('hex');
const got = String(w.signature || '');
const signed = secret && !secret.startsWith('EDIT') && got.length === expect.length && crypto.timingSafeEqual(Buffer.from(got), Buffer.from(expect));
if (!signed) return [];                                // not from Meta (or the app secret is wrong): ignore

const statuses = [], echoes = [];
let msgs = [], contacts = [];
for (const e of w.body.entry || []) for (const ch of e.changes || []) {
  const v = ch.value || {};
  if (String((v.metadata || {}).phone_number_id || '') !== String(num.phone_number_id)) continue;
  if (ch.field === 'messages') {
    for (const s of v.statuses || []) {
      const err = (s.errors || [])[0] || {};
      statuses.push({
        id: s.id, status: s.status, recipient: s.recipient_id,
        billable: s.pricing ? !!s.pricing.billable : null, category: s.pricing ? (s.pricing.category || '') : '',
        error: s.status === 'failed' ? cut(`${err.code || ''} ${err.title || ''} ${(err.error_data || {}).details || err.message || ''}`, 300) : null,
      });
    }
    contacts = contacts.concat(v.contacts || []);
    msgs = msgs.concat(v.messages || []);
  } else if (ch.field === 'smb_message_echoes') {
    for (const x of v.message_echoes || []) {
      const text = x.type === 'text' ? (x.text || {}).body : `[${x.type || 'message'}] ${((x[x.type] || {}).caption) || ''}`;
      echoes.push({ to: String(x.to || ''), id: x.id, text: cut(text, 4000) });
    }
  }
}

let message = null;
if (msgs.length) {
  const from = msgs[0].from;
  const mine = msgs.filter(x => x.from === from);
  const texts = [];
  let media = null, tap = null, quotedId = '', referral = null;
  for (const x of mine) {
    if (x.context && x.context.id && !quotedId) quotedId = x.context.id;
    if (x.referral && !referral) referral = x.referral;
    switch (x.type) {
      case 'text': texts.push(x.text.body); break;
      case 'image': if (!media) media = { kind: 'image', id: x.image.id, mime: x.image.mime_type }; if (x.image.caption) texts.push(x.image.caption); break;
      case 'audio': if (!media) media = { kind: 'audio', id: x.audio.id, mime: x.audio.mime_type }; break;
      case 'video': texts.push('[video] ' + ((x.video || {}).caption || '')); break;
      case 'document': texts.push(`[document ${(x.document || {}).filename || ''}] ${(x.document || {}).caption || ''}`); break;
      case 'location': { const l = x.location || {}; texts.push(`[location ${l.latitude},${l.longitude} ${l.name || ''} ${l.address || ''}]`); break; }
      case 'contacts': { const c = (x.contacts || [])[0] || {}; texts.push(`[contact ${(c.name || {}).formatted_name || ''} ${((c.phones || [])[0] || {}).phone || ''}]`); break; }
      case 'interactive': {
        const it = x.interactive || {};
        const r = it.button_reply || it.list_reply;
        if (r) { tap = tap || { id: r.id, title: r.title }; texts.push(`[tapped: ${r.title}]`); }
        break;
      }
      case 'button': tap = tap || { id: x.button.payload, title: x.button.text }; texts.push(`[tapped: ${x.button.text}]`); break;
      default: break;                                  // reaction, sticker, unsupported, system…
    }
  }
  const text = cut(texts.join('\n'), 1500);
  if (text || media) {
    const last = mine[mine.length - 1];
    const contact = contacts.find(c => c.wa_id === from) || contacts[0] || {};
    message = {
      phone: String(from), waId: last.id, name: cut((contact.profile || {}).name, 80),
      text, media, tap, quotedId,
      referral: referral ? {
        source_id: referral.source_id || '', source_url: referral.source_url || '', source_type: referral.source_type || '',
        headline: cut(referral.headline, 200), body: cut(referral.body, 400),
      } : null,
      ts: Number(last.timestamp) || Math.floor(Date.now() / 1000),
    };
  }
}
return [{ json: { statuses, echoes, message } }];

// One customer turn, whether it came from WhatsApp or from the panel's Test bot (test mode:
// nothing is sent to WhatsApp, rows are marked test). Every later node reads $('Message').
if ($('Verify & Split').isExecuted) {
  const v = $('Verify & Split').first().json;
  const n = $('Number').first().json;
  return [{ json: { ...v.message, lingo_user_id: n.lingo_user_id, phone_number_id: n.phone_number_id, token: n.token, settings: n.settings || {}, test: false, start_product: null } }];
}
const a = $('Panel Action').first().json;
const s = $('Seller').first().json;
return [{ json: { ...a.message, lingo_user_id: s.lingo_user_id, phone_number_id: s.phone_number_id, token: null, settings: s.settings || {}, test: true } }];

// First customer from a NEW ad: one small AI call decides which product the ad sells.
// The answer is saved (bot_ads), so later customers from that ad cost 0 tokens. This is the
// only call that sees the seller's whole product list, once per ad.
const cfg = $('Config').first().json;
const m = $('Message').first().json;
const g = $input.first().json;
const ad = g.ad || {};
const list = (g.products || []).map(p => `${p.id}:${p.n}${p.k ? ' (' + String(p.k).slice(0, 80) + ')' : ''}`).join('\n');
const models = (m.settings || {}).ai_models || {};

return [{ json: {
  stage: 'ad_match',
  model: models.ad_match || cfg.MODEL_FAST,
  req: {
    systemInstruction: { parts: [{ text: 'Which product does this Facebook/Instagram ad sell? Return JSON {"p": product id}, or {"p": 0} if none fits.' }] },
    contents: [{ role: 'user', parts: [{ text: `Ad headline: ${ad.headline || '-'}\nAd text: ${ad.body || '-'}\n\nProducts:\n${list}` }] }],
    generationConfig: {
      maxOutputTokens: 256, responseMimeType: 'application/json',
      responseJsonSchema: { type: 'object', properties: { p: { type: 'integer' } }, required: ['p'] },
    },
  },
} }];

// The ad-match answer → bot_set_ad (0 = nothing fits: the seller picks the product in Lingo → Ads).
const m = $('Message').first().json;
const gate = $('Gate').first().json;
const g = $input.first().json || {};
const raw = ((((g.candidates || [])[0] || {}).content || {}).parts || []).filter(x => !x.thought).map(x => x.text || '').join('');
let pid = 0;
try { pid = Number(JSON.parse(raw.replace(/```(json)?/g, '').trim()).p) || 0; } catch (e) { pid = 0; }
return [{ json: { p: { lingo_user_id: m.lingo_user_id, ad_id: (gate.ad || {}).id, product_id: pid || null, phone: m.phone } } }];

// Voice note / image → a tiny Gemini request that returns very short text. Done once: later
// calls only ever see that text, never the media again.
const cfg = $('Config').first().json;
const m = $('Message').first().json;
let b64 = '';
try { b64 = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('base64'); } catch (e) { b64 = ''; }
const mime = String(m.media.mime || (m.media.kind === 'audio' ? 'audio/ogg' : 'image/jpeg')).split(';')[0].trim();
const models = (m.settings || {}).ai_models || {};

const prompt = m.media.kind === 'audio'
  ? 'Customer voice note to a Sri Lankan shop. Write what they say as short text in the same language (Sinhala script, Singlish or English). Keep names, numbers and addresses exact. Max 40 words. Output only the text.'
  : 'Customer sent this image to a Sri Lankan shop. In max 15 English words say what it shows. If it has an address, phone number, payment slip or order details, copy them exactly. Output only that.';

return [{ json: {
  ok: !!b64,
  stage: 'media',
  model: models.media || cfg.MODEL_FAST,
  req: b64 ? {
    systemInstruction: { parts: [{ text: prompt }] },
    contents: [{ role: 'user', parts: [{ inlineData: { mimeType: mime, data: b64 } }] }],
    generationConfig: { maxOutputTokens: 512 },
  } : { contents: [] },
} }];

// Media description + caption → one text line (max ~40 words).
const m = $('Message').first().json;
const g = $input.first().json || {};
const said = ((((g.candidates || [])[0] || {}).content || {}).parts || [])
  .filter(x => !x.thought).map(x => x.text || '').join(' ').replace(/\s+/g, ' ').trim().split(' ').slice(0, 45).join(' ');

const text = m.media.kind === 'audio'
  ? (m.text ? m.text + ' ' : '') + (said ? `[voice] ${said}` : '[voice note - could not understand]')
  : (said ? `[image: ${said}]` : '[image]') + (m.text ? ' ' + m.text : '');
return [{ json: { text } }];

// One row for the batching buffer (text or the media description), with the AI usage of this
// message's voice note / image / ad match so every call is logged even if the batch moves on.
const m = $('Message').first().json;
const usage = [];
const add = (node, builder) => {
  if (!$(node).isExecuted) return;
  const g = $(node).first().json || {};
  const b = $(builder).first().json || {};
  if (g.usageMetadata) usage.push({ stage: b.stage, model: b.model, usage: g.usageMetadata, ok: !g.error });
};
add('Gemini: Ad Match', 'Build Ad Match');
add('Gemini: Media', 'Build Media Request');
const text = $('Media to Text').isExecuted ? $('Media to Text').first().json.text : m.text;
return [{ json: { p: {
  lingo_user_id: m.lingo_user_id, phone: m.phone, wa_id: m.waId, content: text || '[media]', quoted_id: m.quotedId || null,
  tap: m.tap ? m.tap.id : null, wa_ts: m.ts, test: !!m.test, usage,
} } }];

// More than HISTORY_LIMIT past messages → the older ones (and the old summary) become one ~30-word
// summary. The newest KEEP_LAST stay word for word so a short "ow" / "yes" still makes sense.
// The messages themselves stay in the Inbox; only the AI's view of the chat gets shorter.
const cfg = $('Config').first().json;
const m = $('Message').first().json;
const ctx = $('Claim Batch').first().json;
const h = ctx.history || [];
const keep = Math.max(0, Number(cfg.KEEP_LAST) || 0);
const old = h.slice(0, Math.max(0, h.length - keep));
const label = r => (r === 'c' ? 'C: ' : 'B: ');
const models = (m.settings || {}).ai_models || {};
const lines = (ctx.summary ? ['Summary so far: ' + ctx.summary] : []).concat(old.map(x => label(x.r) + x.c));

return [{ json: {
  upto: old.length ? old[old.length - 1].id : null,
  stage: 'summary',
  model: models.summary || cfg.MODEL_FAST,
  req: {
    systemInstruction: { parts: [{ text: 'Summarize this shop WhatsApp chat in max 30 English words. Keep product names, what the customer asked or decided, order details, and any question we are still waiting on.' }] },
    contents: [{ role: 'user', parts: [{ text: lines.join('\n') }] }],
    generationConfig: { maxOutputTokens: 512 },
  },
} }];

// Level 0 / Level 1: what does the customer want?
//   • Only button / list taps → understood exactly, no AI.
//   • A quick rule matches the WHOLE batched text (hi, ok, kiyada?, a phone number, "ow" while
//     confirming…) → no AI.
//   • Otherwise one small "middle AI" call (prompt mid-3) with only: the current product, ≤4
//     products the database matched, the stage and missing fields, ≤15 FAQ questions, the
//     language, the chat summary + last 2 messages, the quote and the new text.
const cfg = $('Config').first().json;
const m = $('Message').first().json;
const ctx = $('Claim Batch').first().json;
const sum = $('Save Summary').isExecuted ? $('Save Summary').first().json : { summary: ctx.summary, history: ctx.history };
const history = sum.history || [];
const cust = ctx.customer || {};
const settings = ctx.settings || m.settings || {};
const prod = ctx.product;
const matches = ctx.matches || [];
const faqs = ctx.faqs || [];
const qp = ctx.quoted_pids || {};
const stage = cust.stage || 'new';
const cut = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n) + '…' : s; };
const has = v => v !== undefined && v !== null && String(v).trim() !== '';

const msgs = ctx.msgs || [];
const taps = msgs.filter(x => x.tap).map(x => x.tap);
const typedList = msgs.filter(x => !x.tap).map(x => x.t);
const now = cut(typedList.join('\n'), 1500);
const typed = typedList.length > 0 && /\S/.test(now);

let quotedPid = 0;
for (const x of msgs) if (x.qid && qp[x.qid]) quotedPid = Number(qp[x.qid]);

const fields = (Array.isArray(settings.order_fields) && settings.order_fields.length ? settings.order_fields : ['name', 'address', 'contact']);
const o = ctx.order;
let missing = [];
if (o && o.status === 'draft') missing = fields.filter(f => !has(o[f]));

// ---------- level 0: quick rules ----------
const normalize = s => String(s || '').normalize('NFC').toLowerCase()
  .replace(/\p{Extended_Pictographic}/gu, ' ').replace(/[\u{1F3FB}-\u{1F3FF}\u{FE0F}\u{20E3}]/gu, '')
  .replace(/[\p{P}\p{S}]/gu, ' ').replace(/\s+/g, ' ').trim();
let rule = null, c = null;
if (typed && !taps.length) {
  const norm = normalize(now);
  const probe = norm || 'ok';                          // only emojis (👍 🙏) = "ok"
  const compact = probe.replace(/[\s-]/g, '');
  for (const r of ctx.rules || []) {
    if (Array.isArray(r.st) && r.st.length && !r.st.includes(stage)) continue;
    let re;
    try { re = new RegExp(r.re, 'iu'); } catch (e) { continue; }
    if (re.test(probe) || (r.k === 'details' && re.test(compact))) {
      rule = { id: r.id, k: r.k, t: r.t || 'other' };
      c = { k: r.k, t: r.t || 'other', faq: 0, p: 0, q: '', l: '', o: r.k === 'details' ? { ph: compact } : {}, u: false };
      break;
    }
  }
}

// ---------- level 1: the middle AI ----------
const skip = !typed || !!rule;
const label = r => (r === 'c' ? 'C: ' : 'B: ');
const last2 = history.slice(-2);
const stageLine = 'Stage: ' + stage + (missing.length ? ', missing ' + missing.join(', ') : '')
  + (o && o.status === 'draft' && !missing.length ? ', order complete, we asked them to confirm' : '')
  + (o && o.status === 'confirmed' ? ', order confirmed' : '');
const user = [
  'Product: ' + (prod ? `${prod.id}:${prod.name}` : 'unknown'),
  matches.length ? 'Others: ' + matches.map(p => `${p.id}:${p.name}`).join(' | ') : '',
  stageLine,
  faqs.length ? 'FAQs: ' + faqs.map(f => `${f.id}:${cut(f.q, 70)}`).join(' | ') : '',
  `Lang: ${cust.lang || settings.default_lang || 'si'}`,
  (sum.summary || last2.length) ? 'Chat:' + (sum.summary ? '\nSummary: ' + cut(sum.summary, 300) : '') + (last2.length ? '\n' + last2.map(x => label(x.r) + cut(x.c, 200)).join('\n') : '') : '',
  quotedPid ? `Quote: [our msg about product ${quotedPid}]` : '',
  'Now: ' + now,
].filter(Boolean).join('\n');

const system = `Read a Sri Lankan shop's WhatsApp chat. Return JSON.
k: details = gives name/address/phone/quantity | confirm = says yes to our order summary | change = wants to change order details | cancel = cancels | question = asks something | other_product = asks about a product that is not Product | complaint = unhappy or problem with an order | human = wants a person or a call | chat = greeting, thanks, ok, anything else.
t (for question): price | delivery | payment | usage | ingredients | safety | results | stock | contact | shop | other.
faq: id from FAQs if one answers the question, else 0.
p: id from Others if they want that product, else 0.
q: what they want now, max 15 simple English words, topic first. Resolve "meka/eka/this" from Quote and Chat.
l: si = writes Sinhala script, sg = Sinhala in English letters, en ONLY if they ask us to use English; if unsure keep Lang.
o: details found in Now only: n name, a address, ph phone ("same" if they say use this WhatsApp number), qty.
u: true if you are not sure what they mean.`;

const schema = {
  type: 'object',
  properties: {
    k: { type: 'string', enum: ['details', 'confirm', 'change', 'cancel', 'question', 'other_product', 'complaint', 'human', 'chat'] },
    t: { type: 'string', enum: ['price', 'delivery', 'payment', 'usage', 'ingredients', 'safety', 'results', 'stock', 'contact', 'shop', 'other'] },
    faq: { type: 'integer' },
    p: { type: 'integer' },
    q: { type: 'string' },
    l: { type: 'string', enum: ['si', 'sg', 'en'] },
    o: { type: 'object', properties: { n: { type: 'string' }, a: { type: 'string' }, ph: { type: 'string' }, qty: { type: 'integer' } } },
    u: { type: 'boolean' },
  },
  required: ['k', 't', 'faq', 'p', 'q', 'l', 'o', 'u'],
};
const models = settings.ai_models || {};

return [{ json: {
  now, typed, taps, skip, rule, c, stage, missing, quotedPid,
  prompt_version: 'mid-3',
  prompt_chars: skip ? 0 : system.length + user.length,
  stage_name: 'classify',
  model: models.classify || cfg.MODEL_FAST,
  req: skip ? null : {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig: { maxOutputTokens: 1024, responseMimeType: 'application/json', responseJsonSchema: schema },
  },
} }];

// Decides the whole reply in code (a state machine), aiming for a confirmed order:
//   • a product the customer hasn't seen yet → its photo + long description, then ask for details
//   • price / delivery / payment / contact / shop / stock → the seller's fixed text, numbers from
//     the product row (no AI)
//   • an FAQ the middle AI picked → its answer as written (no AI)
//   • a real product question with no FAQ → answer cache, then the reply AI (only the product
//     fields for that topic)
//   • details → ask only for what's missing → summary with Confirm / Change / Cancel
//   • not sure → one clarifying question with buttons; not sure twice, a complaint or "talk to a
//     person" → hand the chat to the seller (Inbox) and pause the bot for it
const cfg = $('Config').first().json;
const m = $('Message').first().json;
const ctx = $('Claim Batch').first().json;
const u = $('Understand').first().json;
const history = $('Save Summary').isExecuted ? ($('Save Summary').first().json.history || []) : (ctx.history || []);
const settings = ctx.settings || m.settings || {};
const cust = ctx.customer || {};
const fixed = ctx.fixed || {};
const matches = ctx.matches || [];
const faqs = ctx.faqs || [];
const budget = ctx.budget || {};

const cut = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n) + '…' : s; };
const has = v => v !== undefined && v !== null && String(v).trim() !== '';
const money = n => Number(n || 0).toLocaleString('en-US', { maximumFractionDigits: 2 });
const gtext = g => ((((g || {}).candidates || [])[0] || {}).content || { parts: [] }).parts.filter(x => !x.thought).map(x => x.text || '').join('');

// ---------- what the customer wants ----------
const KINDS = ['details', 'confirm', 'change', 'cancel', 'question', 'other_product', 'complaint', 'human', 'chat'];
const TOPICS = ['price', 'delivery', 'payment', 'usage', 'ingredients', 'safety', 'results', 'stock', 'contact', 'shop', 'other'];
let c = null;
if (u.rule) c = u.c;
else if ($('Gemini: Classify').isExecuted) {
  try { c = JSON.parse(gtext($('Gemini: Classify').first().json).replace(/```(json)?/g, '').trim()); } catch (e) { c = null; }
  if (!c || !KINDS.includes(c.k)) c = null;                 // invalid output = not sure; a turn never crashes on AI output
}
const unsure = !!u.typed && (!c || c.u === true);
const k = c && !unsure ? c.k : 'chat';
const t = c && TOPICS.includes(c.t) ? c.t : 'other';
const lang = c && ['si', 'sg', 'en'].includes(c.l) ? c.l : (cust.lang || settings.default_lang || 'si');
const L = lang === 'en' ? 'en' : 'si';
const q = cut(String((c && c.q) || '').trim() || u.now, 200);
const o = (c && !unsure && c.o) || {};

// ---------- button / list taps (exact, no AI) ----------
let act = null, pick = 0, info = false, human = false;
for (const id of u.taps || []) {
  if (/^P_\d+$/.test(id)) pick = Number(id.slice(2));
  else if (['ORDER', 'CONFIRM', 'CHANGE', 'CANCEL'].includes(id)) act = id;
  else if (id === 'INFO') info = true;
  else if (id === 'HUMAN') human = true;
}
if (!act) act = { details: 'DETAILS', confirm: 'CONFIRM', change: 'CHANGE', cancel: 'CANCEL' }[k] || null;

// ---------- product: pick → quoted product → current (ad) → the AI's pick among the DB matches ----------
const byId = {};
for (const p of [ctx.product, ...matches]) if (p) byId[Number(p.id)] = p;
let pid = ctx.product ? Number(ctx.product.id) : 0;
let switched = false;
const want = pick || Number(u.quotedPid) || (c && !unsure ? Number(c.p) || 0 : 0) || (!pid && matches.length === 1 ? Number(matches[0].id) : 0);
if (want && byId[want] && want !== pid) { pid = want; switched = true; }
const prod = pid ? byId[pid] : null;
const seen = (cust.seen_products || []).map(Number);

// ---------- order ----------
const fields = Array.isArray(settings.order_fields) && settings.order_fields.length ? settings.order_fields : ['name', 'address', 'contact'];
const gave = has(o.n) || has(o.a) || has(o.ph) || Number(o.qty) > 0;
const lastBot = [...history].reverse().find(x => x.r === 'b');
const changing = !!(lastBot && String(lastBot.c).includes('[asked what to change]'));
let order = ctx.order ? { ...ctx.order } : null;
let target = null, event = '';
const fresh = () => ({ id: null, product_id: null, qty: null, name: null, address: null, contact: null, status: 'draft' });

if (act === 'CANCEL') {
  if (order && order.status !== 'cancelled') { order.status = 'cancelled'; target = order; event = 'cancelled'; }
} else if (act === 'CHANGE' || act === 'CONFIRM') {
  if (order && order.status !== 'cancelled') target = order;
} else if (act === 'ORDER' || act === 'DETAILS' || gave) {
  if (order && (order.status === 'draft' || (order.status === 'confirmed' && changing))) target = order;
  else target = fresh();
}
const missingOf = x => { const mm = fields.filter(f => !has(x[f])); if (!x.product_id) mm.unshift('product'); return mm; };
if (target && event !== 'cancelled') {
  if (has(o.n)) target.name = cut(String(o.n).trim(), 80);
  if (has(o.a)) target.address = cut(String(o.a).trim(), 300);
  if (has(o.ph)) {
    const ph = String(o.ph);
    target.contact = /same|this|meka|මේ/i.test(ph) && !/\d{6,}/.test(ph) ? '0' + String(cust.phone).replace(/^94/, '') : ph.replace(/[^\d+ ]/g, '').trim();
  }
  if (Number(o.qty) > 0) target.qty = Math.min(99, Math.round(Number(o.qty)));
  if (pid && target.status !== 'confirmed' && (!target.product_id || switched)) target.product_id = pid;
  if (!target.qty) target.qty = 1;
  if (act === 'CONFIRM') {
    if (target.status === 'draft' && !missingOf(target).length) { target.status = 'confirmed'; event = 'confirmed'; }
    else if (target.status === 'confirmed') event = 'already';
  } else if (target.status === 'confirmed' && gave) {
    target.status = 'draft';                                  // changed after confirming → confirm again
  }
  order = target;
}
const missing = order && order.status === 'draft' ? missingOf(order) : [];
const complete = !!(order && order.status === 'draft' && !missing.length);

// ---------- fixed texts ----------
const oprod = (order && byId[Number(order.product_id)]) || prod;
const LABEL = { si: { name: 'නම', address: 'ලිපිනය', contact: 'දුරකථන අංකය', product: 'product එක' },
                en: { name: 'name', address: 'address', contact: 'phone number', product: 'product' } }[L];
const missingText = (() => {
  const w = missing.map(x => LABEL[x] || x);
  return w.length < 2 ? w.join('') : w.slice(0, -1).join(', ') + (L === 'en' ? ' and ' : ' සහ ') + w[w.length - 1];
})();
const qty = (order && order.qty) || 1;
const vals = {
  business: settings.business || '', name: (order && order.name) || cust.name || '',
  product: (oprod || {}).name || '', price: money((oprod || {}).price), delivery_fee: money((oprod || {}).delivery_fee),
  qty, address: (order && order.address) || '', contact: (order && order.contact) || '',
  total: money(Number((oprod || {}).price || 0) * qty + Number((oprod || {}).delivery_fee || 0)),
  missing: missingText, shop_phone: settings.shop_phone || '', shop_address: settings.shop_address || '',
  delivery_days: settings.delivery_days || 3,
};
const fill = s => String(s || '').replace(/\{(\w+)\}/g, (x, key) => (key in vals ? String(vals[key]) : x))
  .replace(/[ \t]{2,}/g, ' ').replace(/ ([!?.,])/g, '$1').replace(/\n{3,}/g, '\n\n').trim();
const fx = key => { const f = fixed[key] || {}; return fill(L === 'en' ? (f.en || f.si) : f.si); };
const btn = (id, key) => ({ id, title: fx(key) });
const productList = () => ({ kind: 'list', text: fx('pick_product'), button: fx('btn_menu'),
  rows: matches.map(p => ({ id: `P_${p.id}`, title: p.name, description: p.short_info || '' })) });

// ---------- build the reply ----------
const blocks = [], log = [], seenAdd = [];
let route = u.rule ? 'rule' : (!u.typed ? 'tap' : 'fixed');
let ai = null, faqId = null, handoff = null;

if (human || k === 'human' || k === 'complaint') handoff = { reason: k === 'complaint' ? 'complaint' : 'asked for a person' };
else if (unsure && Number(cust.unsure_streak || 0) + 1 >= 2) handoff = { reason: 'not sure what they mean (twice)' };

if (handoff) {
  blocks.push({ kind: 'text', text: fx('handoff') });
  log.push(`[handed to the shop: ${handoff.reason}]`);
  route = 'human';
} else if (unsure) {
  blocks.push({ kind: 'buttons', text: fx('clarify'), buttons: [btn('ORDER', 'btn_order'), btn('INFO', 'btn_info'), btn('HUMAN', 'btn_human')] });
  log.push('[asked what they mean]');
} else {
  const welcome = !!(prod && (!seen.includes(pid) || info) && !['CONFIRM', 'CANCEL'].includes(act) && !event);
  if (welcome) {
    const desc = fill(prod.long_description || prod.short_info || prod.name);
    blocks.push(prod.image_url ? { kind: 'image', image: prod.image_url, caption: desc, pid } : { kind: 'text', text: desc, pid });
    seenAdd.push(pid);
    log.push(`[sent ${prod.name} photo + details]`);
  }

  if (event === 'cancelled') {
    blocks.push({ kind: 'text', text: fx('order_cancelled') }); log.push('[order cancelled]');
  } else if (event === 'confirmed' || event === 'already') {
    blocks.push({ kind: 'text', text: fx('order_confirmed') }); log.push('[order confirmed]');
  } else if (!prod) {
    if (matches.length > 1) { blocks.push(productList()); log.push('[asked which product]'); }
    else { blocks.push({ kind: 'text', text: fx('ask_product') }); log.push('[asked which product]'); }
  } else {
    // 1) answer what they asked
    const waitingChange = act === 'CHANGE' && !gave;
    if (waitingChange) {
      blocks.push({ kind: 'text', text: fx('ask_change') }); log.push('[asked what to change]');
    } else if (k === 'question') {
      const FIXED_TOPIC = { price: 'price', delivery: 'delivery', payment: 'payment', contact: 'contact', shop: 'shop' };
      const coveredByWelcome = welcome && ['price', 'delivery', 'other'].includes(t);   // the photo text has price & delivery
      const faq = !switched && Number(c.faq) ? faqs.find(f => Number(f.id) === Number(c.faq)) : null;
      const faqAnswer = faq ? (L === 'en' ? (faq.en || faq.si) : (faq.si || faq.en)) : '';
      if (coveredByWelcome) { /* nothing extra */ }
      else if (FIXED_TOPIC[t] && fx(FIXED_TOPIC[t])) { blocks.push({ kind: 'text', text: fx(FIXED_TOPIC[t]) }); log.push(`[answered ${t}]`); }
      else if (t === 'stock') {
        if (fx('stock')) { blocks.push({ kind: 'text', text: fx('stock') }); log.push('[answered stock]'); }
        else { blocks.push({ kind: 'text', text: fx('will_check') }); handoff = { reason: 'stock question (no stock text set)' }; route = 'human'; log.push('[will check stock, handed to the shop]'); }
      } else if (faqAnswer) {
        blocks.push({ kind: 'text', text: fill(faqAnswer) }); faqId = faq.id; route = 'faq'; log.push(`[answered FAQ: ${cut(faq.q, 60)}]`);
      } else {
        blocks.push({ kind: 'ai' }); ai = { topic: t };
      }
    } else if (k === 'other_product' && !switched) {
      if (matches.length > 1) { blocks.push(productList()); log.push('[asked which product]'); }
      else { blocks.push({ kind: 'ai' }); ai = { topic: 'unknown_product' }; }
    }

    // 2) always move towards the order (not after a hand-off)
    if (!waitingChange && !handoff) {
      if (complete) {
        blocks.push({ kind: 'buttons', text: fx('order_summary'),
          buttons: [btn('CONFIRM', 'btn_confirm'), btn('CHANGE', 'btn_change'), btn('CANCEL', 'btn_cancel')] });
        log.push('[sent order summary, asked to confirm]');
      } else if (order && order.status === 'draft' && fields.some(f => has(order[f]))) {
        blocks.push({ kind: 'text', text: fx('ask_missing') });
        log.push(`[asked missing: ${missing.join(', ')}]`);
      } else if (!order || order.status !== 'confirmed') {
        blocks.push({ kind: 'text', text: welcome || act === 'ORDER' ? fx('ask_details') : fx('nudge') });
        log.push('[asked name/address/phone]');
      } else if (!blocks.length) {
        blocks.push({ kind: 'text', text: fx('chat_reply') }); log.push('[said thanks]');
      }
    }
  }
}
if (!blocks.length) { blocks.push({ kind: 'text', text: fx('chat_reply') }); log.push('[said thanks]'); }

// ---------- stage ----------
let stage = cust.stage || 'new';
if (handoff) stage = 'handoff';
else if (event === 'cancelled') stage = 'cancelled';
else if (event === 'confirmed' || event === 'already' || (order && order.status === 'confirmed')) stage = 'ordered';
else if (complete) stage = 'confirming';
else if (order && order.status === 'draft' && fields.some(f => has(order[f]))) stage = 'collecting';
else if (prod && ['new', 'handoff', 'cancelled'].includes(stage)) stage = 'browsing';

// ---------- reply AI request (only real product questions; only that topic's fields, ≤600 chars) ----------
let aiReq = null, facts = '';
if (ai && prod) {
  const langName = { si: 'Sinhala (Sinhala script)', sg: 'Singlish (Sinhala written in English letters)', en: 'English' }[lang];
  const list = {
    usage: [prod.usage],
    ingredients: [prod.ingredients],
    safety: [prod.precautions, prod.usage],
    results: [prod.short_info, prod.symptoms],
    unknown_product: ['We do not have details of that product here. We only have the products we sell.'],
  }[ai.topic] || [prod.short_info, prod.usage, prod.precautions];
  facts = cut(list.filter(has).join(' | ') || 'No details.', 600);
  const sys = `You are a staff member at a Sri Lankan online shop, answering a customer on WhatsApp. Never say you are a bot or AI.
Answer only the question, like a real person: 1-3 short sentences, polite, not over-friendly, 1-2 fitting emojis.
Use only the facts. Never invent anything, including numbers; if the facts don't answer it, say you will check and reply soon.
Health products: never promise a cure and never tell anyone to stop a doctor's medicine; for pregnancy, children, long-term illness or other medicines, advise checking with a doctor.
Do not ask for order details. Return JSON {"r": reply}.`;
  aiReq = {
    systemInstruction: { parts: [{ text: sys }] },
    contents: [{ role: 'user', parts: [{ text: `Product: ${prod.name}\nFacts: ${facts}\nCustomer: ${q}\nWrite in ${langName}.` }] }],
    generationConfig: {
      maxOutputTokens: 1024, responseMimeType: 'application/json',
      responseJsonSchema: { type: 'object', properties: { r: { type: 'string' } }, required: ['r'] },
    },
  };
  if (has(cfg.REPLY_THINKING)) aiReq.generationConfig.thinkingConfig = { thinkingLevel: String(cfg.REPLY_THINKING) };
}
const models = settings.ai_models || {};

return [{ json: {
  route: aiReq ? 'ai' : 'send',
  final_route: route,
  lang, blocks, req: aiReq,
  stage_name: 'reply',
  model: models.reply || cfg.MODEL_REPLY,
  degrade: !!budget.degrade,
  cache: aiReq ? { facts_hash: prod.facts_hash, t: ai.topic, lang, q } : null,
  guard: aiReq ? {
    facts: [facts, prod.price, prod.delivery_fee, Number(prod.price || 0) + Number(prod.delivery_fee || 0), settings.shop_phone, settings.delivery_days].join(' '),
    banned: (settings.banned_claims || []).map(x => String(x).toLowerCase()).filter(Boolean),
    product_id: prod.id, product_id_feeder: prod.feeder_id,
  } : null,
  fixed_will_check: fx('will_check'),
  save: {
    lingo_user_id: m.lingo_user_id, phone: m.phone, test: !!m.test,
    msgs: (ctx.msgs || []).map(x => ({ wa_id: x.wa_id, t: x.t })),
    log: log.join('\n'),
    meta: { k: c ? c.k : null, t: c ? c.t : null, q, faq: c ? Number(c.faq) || 0 : 0, u: unsure, rule: u.rule ? u.rule.id : null, pid: pid || null, prompt: u.prompt_version },
    product_id: pid || null,
    seen_add: seenAdd,
    lang, stage,
    unsure: unsure && !handoff,
    handoff,
    route,
    faq_id: faqId,
    rule_id: u.rule ? u.rule.id : null,
    order: target ? {
      id: order.id || null, product_id: order.product_id || null, qty: order.qty || 1,
      name: order.name || null, address: order.address || null, contact: order.contact || null, status: order.status,
    } : null,
  },
} }];

// Puts the answer for a real product question into the reply: a saved answer (cache), or the reply
// AI's answer after the OUTPUT GUARD (code): no banned claims, every number must be in the facts,
// short enough, and in the customer's script. A failed check, or no AI allowance left this month
// (degrade mode), sends "we'll check and reply" and hands the chat to the seller.
const plan = $('Plan Reply').first().json;
const cache = $('Cache Get').isExecuted ? $('Cache Get').first().json : {};
const g = $('Gemini: Reply').isExecuted ? ($('Gemini: Reply').first().json || {}) : null;
const gtext = x => ((((x || {}).candidates || [])[0] || {}).content || { parts: [] }).parts.filter(p => !p.thought).map(p => p.text || '').join('');

let r = '', route = 'ai', why = '', cacheKey = null, cachePut = null;
if (cache.hit && cache.answer) {
  r = String(cache.answer); route = 'cache'; cacheKey = cache.key;
} else if (!g) {
  why = 'AI allowance used up this month';
} else {
  const raw = gtext(g);
  try { r = String(JSON.parse(raw.replace(/```(json)?/g, '').trim()).r || '').trim(); } catch (e) { r = raw.trim(); }
  if (!r) why = g.error ? 'AI call failed' : 'empty AI answer';
  if (!why) {
    const low = r.toLowerCase();
    const banned = (plan.guard.banned || []).find(b => low.includes(b));
    const nums = s => (String(s).match(/\d+(?:[.,]\d+)*/g) || []).map(x => x.replace(/,/g, '').replace(/\.0+$/, '').replace(/^0+(?=\d)/, ''));
    const allowed = new Set(nums(plan.guard.facts));
    const strange = nums(r).filter(n => !allowed.has(n));
    const sinhala = (r.match(/[඀-෿]/g) || []).length;
    const latin = (r.match(/[A-Za-z]/g) || []).length;
    if (banned) why = `banned claim: ${banned}`;
    else if (strange.length) why = `number not in the facts: ${strange.slice(0, 3).join(', ')}`;
    else if (Array.from(r).length > 600) why = 'answer too long';
    else if (plan.lang === 'si' && sinhala < latin * 0.5) why = 'not in Sinhala script';
    else if ((plan.lang === 'sg' || plan.lang === 'en') && sinhala > 0) why = 'Sinhala script for a Singlish/English customer';
  }
  if (!why && plan.cache) cachePut = { ...plan.cache, answer: r, product_id: plan.guard.product_id, product_id_feeder: plan.guard.product_id_feeder };
}

let blocks, save = { ...plan.save };
if (why) {
  blocks = plan.blocks.filter(b => b.kind === 'image' || (b.kind === 'text' && b.pid)).concat([{ kind: 'text', text: plan.fixed_will_check }]);
  save.handoff = { reason: `will check: ${why}`, q: plan.save.meta.q };
  save.stage = 'handoff';
  save.unsure = false;
  route = 'human';
  save.log = [save.log, `[will check, handed to the shop: ${why}]`].filter(Boolean).join('\n');
} else {
  blocks = plan.blocks.map(b => (b.kind === 'ai' ? { kind: 'text', text: r } : b));
  save.log = [r ? `[answered: ${r.slice(0, 160)}]` : '', save.log].filter(Boolean).join('\n');
}
save.route = route;
save.cache_key = cacheKey;
save.cache_put = cachePut;
return [{ json: { blocks, save } }];

// Reply blocks → WhatsApp Cloud API messages. Neighbouring texts are merged into one message
// (fewer messages = cheaper outside free windows). Limits: buttons ≤3 (titles ≤20), list rows ≤10
// (titles ≤24, descriptions ≤72), body / caption ≤1024, text ≤4096.
const m = $('Message').first().json;
const src = $input.first().json;
const to = String(m.phone);
const clip = (s, n) => Array.from(String(s || '')).slice(0, n).join('');
const len = s => Array.from(String(s || '')).length;
const base = { messaging_product: 'whatsapp', recipient_type: 'individual', to };

const out = [];
let pend = '', pendPid = null;
const push = (pid, body, text) => out.push({ json: { pid, text, body, url: `https://graph.facebook.com/${$('Config').first().json.GRAPH_VERSION}/${m.phone_number_id}/messages` } });
const flush = () => {
  if (!pend) return;
  push(pendPid, { ...base, type: 'text', text: { body: clip(pend, 4096), preview_url: false } }, clip(pend, 4096));
  pend = ''; pendPid = null;
};
const join = (a, b) => (a ? a + '\n\n' + b : b);

for (const b of src.blocks || []) {
  if (b.kind === 'text') {
    if (!b.text) continue;
    if (len(join(pend, b.text)) > 4096) flush();
    pend = join(pend, b.text);
    if (b.pid) pendPid = b.pid;
  } else if (b.kind === 'image') {
    flush();
    if (len(b.caption) <= 1024) {
      push(b.pid, { ...base, type: 'image', image: { link: b.image, caption: b.caption || '' } }, '[photo] ' + (b.caption || ''));
    } else {
      push(b.pid, { ...base, type: 'image', image: { link: b.image } }, '[photo]');
      pend = b.caption; pendPid = b.pid;
    }
  } else if (b.kind === 'buttons' || b.kind === 'list') {
    let text = join(pend, b.text);
    if (len(text) > 1024) { flush(); text = b.text; }
    const pid = pendPid; pend = ''; pendPid = null;
    const action = b.kind === 'buttons'
      ? { buttons: b.buttons.slice(0, 3).map(x => ({ type: 'reply', reply: { id: x.id, title: clip(x.title, 20) } })) }
      : { button: clip(b.button, 20), sections: [{ title: 'Products', rows: b.rows.slice(0, 10).map(r => ({
          id: r.id, title: clip(r.title, 24), description: clip(r.description, 72) })) }] };
    const labels = b.kind === 'buttons' ? action.buttons.map(x => x.reply.title) : action.sections[0].rows.map(x => x.title);
    push(pid, { ...base, type: 'interactive', interactive: { type: b.kind === 'buttons' ? 'button' : 'list', body: { text: clip(text, 1024) }, action } },
      clip(text, 1024) + '\n[' + labels.join(' | ') + ']');
  }
}
flush();
return out;

// Collects what was sent (WhatsApp ids for delivery statuses and quote matching) and every AI call's
// usage, then saves the whole turn in one database call. In test mode nothing was sent.
const m = $('Message').first().json;
const src = $('Compose Reply').isExecuted ? $('Compose Reply').first().json : $('Plan Reply').first().json;
const outs = $('Split Outgoing').all();
const results = m.test ? [] : $input.all();
const sent = [], productMsgs = [];
outs.forEach((o, i) => {
  const r = results[i] ? (results[i].json || {}) : {};
  const id = ((r.messages || [])[0] || {}).id || null;
  const e = r.error ? (typeof r.error === 'string' ? r.error : `${r.error.code || ''} ${r.error.message || ''}`.trim()) : null;
  sent.push({ wa_id: id, text: o.json.text, error: m.test ? null : (e || (id ? null : 'no message id')) });
  if (o.json.pid && id) productMsgs.push({ wa_id: id, product_id: o.json.pid });
});

const usage = [];
const add = (node, builder) => {
  if (!$(node).isExecuted) return;
  const g = $(node).first().json || {};
  const b = $(builder).first().json || {};
  if (g.usageMetadata) usage.push({ stage: b.stage_name || b.stage, model: b.model, usage: g.usageMetadata, ok: !g.error });
};
add('Gemini: Summary', 'Build Summary Request');
add('Gemini: Classify', 'Understand');
add('Gemini: Reply', 'Plan Reply');

return [{ json: { p: { ...src.save, sent, product_msgs: productMsgs, usage } } }];

// Test bot (feeder.retexia.com → Lingo → Test bot): what the customer would have received, how the
// turn was answered and what the AI cost — the same pipeline as a real WhatsApp message.
const m = $('Message').first().json;
const gate = $('Gate').isExecuted ? $('Gate').first().json : {};
if (!$('Save Turn').isExecuted) {
  const claim = $('Claim Batch').isExecuted ? $('Claim Batch').first().json : {};
  return [{ json: { reply: { ok: true, stopped: gate.status !== 'ok' ? gate.status : (claim.why || 'stopped'), messages: [] } } }];
}
const st = $('Build Save Turn').first().json.p;
const saved = $('Save Turn').first().json || {};
return [{ json: { reply: {
  ok: true,
  phone: m.phone,
  route: st.route,
  stage: st.stage,
  lang: st.lang,
  handoff: st.handoff || null,
